const P=(s,n)=>n+(s-2)*n*(n-1)/2;
let checks=0, failures=[];
for(let n=1;n<=200;n++)for(let s=3;s<=20;s++){
 for(const [actual,expected] of [[4*P(s,n)-P(s,2*n),(4-s)*n],[4*P(s,n)-P(s,2*n-1),s*n+3-s]]){checks++;if(actual!==expected)failures.push({s,n,actual,expected});}
}
